import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { registerEssenceHandler } from "../handlers/registerEssenceHandler";
import type { ApiError } from "../runtime/client";
import type { FactFoldRoundEntityType } from "../types/FactFoldRoundEntityType";
import type { RegisterEssenceRequest } from "../types/RegisterEssenceRequest";

type Data = Awaited<ReturnType<typeof registerEssenceHandler>>;
type Vars = { roundId: FactFoldRoundEntityType; req: RegisterEssenceRequest };

export function useRegisterEssence(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => registerEssenceHandler(vars.roundId, vars.req),
    ...options,
  });
}
